    auto_generate_report_on_end boolean DEFAULT true NOT NULL,
    default_branch_id integer,
    require_branch_selection boolean DEFAULT false NOT NULL,
    ai_model text DEFAULT 'claude-haiku-4-5'::text NOT NULL,
    idle_timeout_minutes integer,
    updated_by_user_id integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    session_start_time text,
    session_end_time text,
    end_warning_minutes integer DEFAULT 15
